import{_ as e,c as o,o as a,a4 as t}from"./chunks/framework.DzOtv0XR.js";const x=JSON.parse('{"title":"Mobx","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/mobx.md","filePath":"frameworks/mobx.md"}'),r={name:"frameworks/mobx.md"},c=t('<h1 id="mobx" tabindex="-1">Mobx <a class="header-anchor" href="#mobx" aria-label="Permalink to &quot;Mobx&quot;">​</a></h1><ul><li>autorun 立即执行一次</li><li>reaction(() =&gt; data, () =&gt; {}) 第一个参数返回观察数据</li><li>when(() =&gt; boolean, () =&gt; {}) 第一参数返回布尔值，为真时执行一次，然后销毁</li></ul><p><a href="https://zhuanlan.zhihu.com/p/24613915" target="_blank" rel="noreferrer">[干货] 使用 Mobx 更好地处理 React 数据 - 知乎专栏</a></p><h2 id="子组件较多时-如何用-mobx-传递和共享数据" tabindex="-1">子组件较多时，如何用 mobx 传递和共享数据 <a class="header-anchor" href="#子组件较多时-如何用-mobx-传递和共享数据" aria-label="Permalink to &quot;子组件较多时，如何用 mobx 传递和共享数据&quot;">​</a></h2><p>眼下的做法是父子共用一个 store，缺点是相互影响，很多数据需要手动重置</p><p>正确的做法是严格从上往下传数据，下级如果要改数据，使用回调</p><p>答案是 Provider 和 inject</p><h2 id="mobx-react" tabindex="-1">mobx-react <a class="header-anchor" href="#mobx-react" aria-label="Permalink to &quot;mobx-react&quot;">​</a></h2><ul><li><p><code>Observer</code>是一个组件，应用<code>observer</code>到你的组件的匿名区域，接受一个无参数函数，精确返回一个组件 使用装饰器，不用关注这一点</p></li><li><p><code>onError</code>全局错误处理，能避免导致应用崩溃，而是打印到日志</p></li><li><p>哪些组件应该标记为<code>observer</code>? 所有需要渲染可观察数据的组件</p></li><li><p><code>shouldComponentUpdate</code>应避免使用，由于 mobx 会默认提供一个高度优化的<code>shouldComponentUpdate</code>实现</p></li><li><p><code>componentWillReact</code> 是自动的，mobx 的数据变化，就会响应</p></li><li><p><code>Provider</code>是一个组件，通过 React 的上下文机制传递 stores 给子组件，而<code>inject</code>则是选取 stores 同时使用<code>@inject</code>和<code>@observer</code>时，<code>@inject</code>写在外面</p></li></ul><h2 id="学习-mobx-react-todomvc" tabindex="-1">学习 mobx-react-todomvc <a class="header-anchor" href="#学习-mobx-react-todomvc" aria-label="Permalink to &quot;学习 mobx-react-todomvc&quot;">​</a></h2><ul><li>多了个 todoModal 类，传四个参数，store, id, title, completed 一些 todo 操作方法，加上与对象转换的方法</li><li>id 随机生成</li><li>子组件之所以能修改数据，就是从父级传下来不只是某个值，而是包括修改方法的类</li></ul>',11),d=[c];function l(i,n,m,s,p,b){return a(),o("div",null,d)}const _=e(r,[["render",l]]);export{x as __pageData,_ as default};
